import { sql } from "drizzle-orm";
import {
  boolean,
  check,
  index,
  integer,
  jsonb,
  pgEnum,
  pgTable,
  primaryKey,
  smallint,
  text,
  timestamp,
  uniqueIndex,
  uuid,
} from "drizzle-orm/pg-core";

// Conventions: money is integer paise, timestamps are UTC `timestamptz`,
// ids are uuid v4 generated by Postgres.

const id = () => uuid("id").primaryKey().defaultRandom();
const createdAt = () => timestamp("created_at", { withTimezone: true }).notNull().defaultNow();
const updatedAt = () => timestamp("updated_at", { withTimezone: true }).notNull().defaultNow();

// ---------------------------------------------------------------------------
// Identity
// ---------------------------------------------------------------------------

/** How a browser first reached YOLT (decision D16). First visit decides; it is never overwritten. */
export type FirstTouch = { type: "SELLER_LINK"; sellerHandle: string; at: string } | { type: "YOLT"; at: string };

export const users = pgTable("users", {
  id: id(),
  /** E.164, e.g. +919876543210 */
  phone: text("phone").unique(),
  phoneVerifiedAt: timestamp("phone_verified_at", { withTimezone: true }),
  email: text("email").unique(),
  name: text("name"),
  firstTouch: jsonb("first_touch").$type<FirstTouch>(),
  createdAt: createdAt(),
});

/**
 * YOLT staff. Granted only from the command line (`pnpm admin:grant`), never through the app,
 * so no account can make itself an admin.
 */
export const adminRole = pgEnum("admin_role", ["ADMIN", "SUPPORT"]);

export const admins = pgTable("admins", {
  userId: uuid("user_id").primaryKey().references(() => users.id),
  role: adminRole("role").notNull(),
  grantedBy: text("granted_by").notNull(),
  createdAt: createdAt(),
});

export const otpChannel = pgEnum("otp_channel", ["WHATSAPP", "SMS"]);

/** One-time login codes. Only an HMAC of the code is stored. */
export const otpChallenges = pgTable(
  "otp_challenges",
  {
    id: id(),
    phone: text("phone").notNull(),
    codeHash: text("code_hash").notNull(),
    channel: otpChannel("channel").notNull(),
    attempts: smallint("attempts").notNull().default(0),
    /** Hashed client IP, for per-network rate limits without storing raw IPs. */
    ipHash: text("ip_hash"),
    expiresAt: timestamp("expires_at", { withTimezone: true }).notNull(),
    consumedAt: timestamp("consumed_at", { withTimezone: true }),
    createdAt: createdAt(),
  },
  (t) => [index("otp_phone_created_idx").on(t.phone, t.createdAt), index("otp_ip_created_idx").on(t.ipHash, t.createdAt)],
);

/** Login sessions. The cookie holds a random token; only its SHA-256 is stored, so a DB leak can't be replayed. */
export const sessions = pgTable(
  "sessions",
  {
    id: id(),
    userId: uuid("user_id").notNull().references(() => users.id),
    tokenHash: text("token_hash").notNull().unique(),
    userAgent: text("user_agent"),
    createdAt: createdAt(),
    lastSeenAt: timestamp("last_seen_at", { withTimezone: true }).notNull().defaultNow(),
    expiresAt: timestamp("expires_at", { withTimezone: true }).notNull(),
    revokedAt: timestamp("revoked_at", { withTimezone: true }),
  },
  (t) => [index("sessions_user_idx").on(t.userId)],
);

export const addresses = pgTable(
  "addresses",
  {
    id: id(),
    userId: uuid("user_id").notNull().references(() => users.id),
    name: text("name").notNull(),
    phone: text("phone").notNull(),
    line1: text("line1").notNull(),
    line2: text("line2"),
    landmark: text("landmark"),
    city: text("city").notNull(),
    state: text("state").notNull(),
    pincode: text("pincode").notNull(),
    isDefault: boolean("is_default").notNull().default(false),
    createdAt: createdAt(),
  },
  (t) => [
    index("addresses_user_idx").on(t.userId),
    // At most one default address per user.
    uniqueIndex("addresses_one_default_per_user").on(t.userId).where(sql`${t.isDefault}`),
  ],
);

// ---------------------------------------------------------------------------
// Sellers
// ---------------------------------------------------------------------------

export const sellerTrack = pgEnum("seller_track", ["STORE", "CLOSET"]);
export const sellerStatus = pgEnum("seller_status", ["APPLIED", "APPROVED", "REJECTED", "SUSPENDED"]);
export const kycStatus = pgEnum("kyc_status", ["NOT_STARTED", "PENDING", "VERIFIED", "FAILED"]);

export const sellers = pgTable("sellers", {
  id: id(),
  userId: uuid("user_id").notNull().unique().references(() => users.id),
  track: sellerTrack("track").notNull(),
  status: sellerStatus("status").notNull().default("APPLIED"),
  kycStatus: kycStatus("kyc_status").notNull().default("NOT_STARTED"),
  /** URL slug, e.g. yolt.in/s/thrifttrove */
  handle: text("handle").notNull().unique(),
  displayName: text("display_name").notNull(),
  bio: text("bio"),
  logoUrl: text("logo_url"),
  /** Object keys for the uploaded logo and banner, so a replaced image can be deleted from storage. */
  logoKey: text("logo_key"),
  bannerUrl: text("banner_url"),
  bannerKey: text("banner_key"),
  instagramHandle: text("instagram_handle"),
  instagramVerifiedAt: timestamp("instagram_verified_at", { withTimezone: true }),
  gstin: text("gstin"),
  /** Pickup state; used if unregistered sellers must be limited to intra-state sales (legal check L2). */
  pickupState: text("pickup_state"),
  /** Where couriers collect parcels; used for delivery estimates. */
  pickupPincode: text("pickup_pincode"),
  /** The rest of the pickup address (same shape as a delivery address), filled in store settings. */
  pickupName: text("pickup_name"),
  pickupPhone: text("pickup_phone"),
  pickupLine1: text("pickup_line1"),
  pickupLine2: text("pickup_line2"),
  pickupLandmark: text("pickup_landmark"),
  pickupCity: text("pickup_city"),
  shippingFeePaise: integer("shipping_fee_paise").notNull().default(0),
  freeShippingAbovePaise: integer("free_shipping_above_paise"),
  dispatchDays: smallint("dispatch_days").notNull().default(2),
  createdAt: createdAt(),
  updatedAt: updatedAt(),
});

// ---------------------------------------------------------------------------
// Drops
// ---------------------------------------------------------------------------

export const dropStatus = pgEnum("drop_status", ["DRAFT", "SCHEDULED", "LIVE", "ENDED", "CANCELLED"]);

export const drops = pgTable(
  "drops",
  {
    id: id(),
    sellerId: uuid("seller_id").notNull().references(() => sellers.id),
    title: text("title").notNull(),
    coverUrl: text("cover_url"),
    startsAt: timestamp("starts_at", { withTimezone: true }).notNull(),
    status: dropStatus("status").notNull().default("DRAFT"),
    maxHoldsPerBuyer: smallint("max_holds_per_buyer").notNull().default(2),
    /** When the "starting soon" reminder was queued, so it's sent once. */
    remindersQueuedAt: timestamp("reminders_queued_at", { withTimezone: true }),
    openedAt: timestamp("opened_at", { withTimezone: true }),
    createdAt: createdAt(),
  },
  (t) => [
    index("drops_seller_idx").on(t.sellerId),
    index("drops_starts_idx").on(t.startsAt),
    check("drops_max_holds_range", sql`${t.maxHoldsPerBuyer} BETWEEN 1 AND 5`),
  ],
);

/** "Remind me" for a drop. Delivery (WhatsApp/push) reads these when the drop is about to open. */
export const dropReminders = pgTable(
  "drop_reminders",
  {
    userId: uuid("user_id").notNull().references(() => users.id),
    dropId: uuid("drop_id").notNull().references(() => drops.id),
    createdAt: createdAt(),
  },
  (t) => [primaryKey({ columns: [t.userId, t.dropId] }), index("drop_reminders_drop_idx").on(t.dropId)],
);

// ---------------------------------------------------------------------------
// Catalog
// ---------------------------------------------------------------------------

export const listingStatus = pgEnum("listing_status", [
  "DRAFT",
  "SCHEDULED", // in an upcoming drop ("Coming soon")
  "AVAILABLE",
  "RESERVED", // an active hold exists
  "PAYMENT_PENDING", // hold owner has started paying
  "SOLD",
  "SOLD_ELSEWHERE", // seller sold it on Instagram / in person
  "WITHDRAWN",
]);

export const conditionGrade = pgEnum("condition_grade", ["NEW_WITH_TAGS", "LIKE_NEW", "GOOD", "FAIR"]);

export const photoKind = pgEnum("photo_kind", ["FRONT", "BACK", "LABEL", "FLAW", "DETAIL", "PROOF_OF_PURCHASE"]);

export type { Measurements } from "@yolt/shared";
import type { Measurements } from "@yolt/shared";

export const listings = pgTable(
  "listings",
  {
    id: id(),
    sellerId: uuid("seller_id").notNull().references(() => sellers.id),
    dropId: uuid("drop_id").references(() => drops.id),
    slug: text("slug").notNull().unique(),
    title: text("title"),
    description: text("description"),
    category: text("category"),
    brandDeclared: text("brand_declared"),
    tagSize: text("tag_size"),
    measurements: jsonb("measurements").$type<Measurements>().notNull().default({}),
    condition: conditionGrade("condition"),
    flaws: text("flaws"),
    /** Seller explicitly ticked "no flaws" — an empty flaws field alone is not enough. */
    noFlawsConfirmed: boolean("no_flaws_confirmed").notNull().default(false),
    pricePaise: integer("price_paise"),
    currency: text("currency").notNull().default("INR"),
    status: listingStatus("status").notNull().default("DRAFT"),
    /** The hold that currently owns this item. Acts as the generation token for releases. */
    currentHoldId: uuid("current_hold_id"),
    allowOffers: boolean("allow_offers").notNull().default(false),
    publishedAt: timestamp("published_at", { withTimezone: true }),
    soldAt: timestamp("sold_at", { withTimezone: true }),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    index("listings_seller_status_idx").on(t.sellerId, t.status),
    index("listings_status_published_idx").on(t.status, t.publishedAt),
    index("listings_drop_idx").on(t.dropId),
    check("listings_price_positive", sql`${t.pricePaise} > 0`),
    // Drafts may be half-filled; anything past DRAFT must have the essentials.
    check(
      "listings_complete_unless_draft",
      sql`${t.status} = 'DRAFT' OR (${t.title} IS NOT NULL AND ${t.category} IS NOT NULL AND ${t.condition} IS NOT NULL AND ${t.pricePaise} IS NOT NULL)`,
    ),
    check(
      "listings_hold_matches_status",
      sql`(${t.currentHoldId} IS NULL) = (${t.status} NOT IN ('RESERVED', 'PAYMENT_PENDING'))`,
    ),
  ],
);

export const listingPhotos = pgTable(
  "listing_photos",
  {
    id: id(),
    listingId: uuid("listing_id").notNull().references(() => listings.id, { onDelete: "cascade" }),
    url: text("url").notNull(),
    /** Object key in media storage; null for externally hosted demo images. */
    storageKey: text("storage_key"),
    width: integer("width"),
    height: integer("height"),
    kind: photoKind("kind").notNull(),
    caption: text("caption"),
    position: smallint("position").notNull(),
  },
  (t) => [uniqueIndex("listing_photos_position_uq").on(t.listingId, t.position)],
);

// ---------------------------------------------------------------------------
// Holds (reservations)
// ---------------------------------------------------------------------------

export const holdStatus = pgEnum("hold_status", ["ACTIVE", "CONVERTED", "EXPIRED", "RELEASED"]);
export const holdSource = pgEnum("hold_source", ["CHECKOUT", "OFFER", "DROP_CLAIM"]);

export const holds = pgTable(
  "holds",
  {
    id: id(),
    listingId: uuid("listing_id").notNull().references(() => listings.id),
    buyerId: uuid("buyer_id").notNull().references(() => users.id),
    orderId: uuid("order_id").notNull(),
    source: holdSource("source").notNull(),
    status: holdStatus("status").notNull().default("ACTIVE"),
    expiresAt: timestamp("expires_at", { withTimezone: true }).notNull(),
    createdAt: createdAt(),
    endedAt: timestamp("ended_at", { withTimezone: true }),
  },
  (t) => [
    // At most one active hold per garment, enforced by Postgres.
    uniqueIndex("holds_one_active_per_listing").on(t.listingId).where(sql`${t.status} = 'ACTIVE'`),
    index("holds_active_expiry_idx").on(t.expiresAt).where(sql`${t.status} = 'ACTIVE'`),
    index("holds_order_idx").on(t.orderId),
  ],
);

// ---------------------------------------------------------------------------
// Orders and payments
// ---------------------------------------------------------------------------

export const orderStatus = pgEnum("order_status", [
  "AWAITING_PAYMENT",
  "CONFIRMED",
  "PACKED",
  "SHIPPED",
  "DELIVERED",
  "CLOSED",
  "EXPIRED", // hold ran out before payment
  "CANCELLED_BY_BUYER",
  "CANCELLED_BY_SELLER",
  "NEEDS_REFUND", // paid, but the item could not be allocated (late payment)
]);

/** Decision D16: did the seller bring this buyer (their share link) or did YOLT? */
export const orderSource = pgEnum("order_source", ["SELLER_LINK", "YOLT_DISCOVERY"]);

export type AddressSnapshot = {
  name: string;
  phone: string;
  line1: string;
  line2?: string | null;
  landmark?: string | null;
  city: string;
  state: string;
  pincode: string;
};

export const orders = pgTable(
  "orders",
  {
    id: id(),
    /** Human-friendly reference shown to buyers and support, e.g. YL-7Q4K2M. */
    reference: text("reference").notNull().unique(),
    buyerId: uuid("buyer_id").notNull().references(() => users.id),
    sellerId: uuid("seller_id").notNull().references(() => sellers.id),
    status: orderStatus("status").notNull().default("AWAITING_PAYMENT"),
    source: orderSource("source").notNull().default("YOLT_DISCOVERY"),
    subtotalPaise: integer("subtotal_paise").notNull(),
    shippingPaise: integer("shipping_paise").notNull(),
    platformFeePaise: integer("platform_fee_paise").notNull().default(0),
    totalPaise: integer("total_paise").notNull(),
    currency: text("currency").notNull().default("INR"),
    shippingAddress: jsonb("shipping_address").$type<AddressSnapshot>(),
    dispatchBy: timestamp("dispatch_by", { withTimezone: true }),
    confirmedAt: timestamp("confirmed_at", { withTimezone: true }),
    packedAt: timestamp("packed_at", { withTimezone: true }),
    shippedAt: timestamp("shipped_at", { withTimezone: true }),
    deliveredAt: timestamp("delivered_at", { withTimezone: true }),
    closedAt: timestamp("closed_at", { withTimezone: true }),
    cancelledAt: timestamp("cancelled_at", { withTimezone: true }),
    cancelReason: text("cancel_reason"),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    index("orders_buyer_idx").on(t.buyerId, t.createdAt),
    index("orders_seller_idx").on(t.sellerId, t.status),
    check("orders_total_matches", sql`${t.totalPaise} = ${t.subtotalPaise} + ${t.shippingPaise} + ${t.platformFeePaise}`),
  ],
);

/** Immutable copy of the listing as the buyer saw it at checkout. */
export type ListingSnapshot = {
  title: string;
  category: string;
  brandDeclared: string | null;
  tagSize: string | null;
  measurements: Measurements;
  condition: string;
  flaws: string | null;
  photoUrl: string | null;
};

export const orderItems = pgTable(
  "order_items",
  {
    id: id(),
    orderId: uuid("order_id").notNull().references(() => orders.id),
    listingId: uuid("listing_id").notNull().references(() => listings.id),
    pricePaise: integer("price_paise").notNull(),
    snapshot: jsonb("snapshot").$type<ListingSnapshot>().notNull(),
    /** True once this garment is allocated to this order after payment. */
    allocated: boolean("allocated").notNull().default(false),
  },
  (t) => [
    uniqueIndex("order_items_order_listing_uq").on(t.orderId, t.listingId),
    // One garment can belong to at most one paid purchase — the last line of defence against overselling.
    uniqueIndex("order_items_one_allocation_per_listing").on(t.listingId).where(sql`${t.allocated}`),
  ],
);

export const paymentStatus = pgEnum("payment_status", ["CREATED", "PENDING", "SUCCEEDED", "FAILED", "UNKNOWN"]);

export const paymentAttempts = pgTable(
  "payment_attempts",
  {
    id: id(),
    orderId: uuid("order_id").notNull().references(() => orders.id),
    provider: text("provider").notNull(),
    providerOrderId: text("provider_order_id"),
    amountPaise: integer("amount_paise").notNull(),
    currency: text("currency").notNull().default("INR"),
    status: paymentStatus("status").notNull().default("CREATED"),
    providerPaymentId: text("provider_payment_id"),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    uniqueIndex("payment_attempts_provider_order_uq").on(t.provider, t.providerOrderId),
    index("payment_attempts_order_idx").on(t.orderId),
  ],
);

/** Every provider webhook we accept, deduplicated by the provider's event id. */
export const paymentEvents = pgTable(
  "payment_events",
  {
    id: id(),
    provider: text("provider").notNull(),
    providerEventId: text("provider_event_id").notNull(),
    type: text("type").notNull(),
    payload: jsonb("payload").notNull(),
    receivedAt: timestamp("received_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [uniqueIndex("payment_events_provider_event_uq").on(t.provider, t.providerEventId)],
);

export const refundStatus = pgEnum("refund_status", ["REQUESTED", "PROCESSING", "SUCCEEDED", "FAILED"]);

export const refunds = pgTable(
  "refunds",
  {
    id: id(),
    orderId: uuid("order_id").notNull().references(() => orders.id),
    paymentAttemptId: uuid("payment_attempt_id").notNull().references(() => paymentAttempts.id),
    amountPaise: integer("amount_paise").notNull(),
    reason: text("reason").notNull(),
    status: refundStatus("status").notNull().default("REQUESTED"),
    providerRefundId: text("provider_refund_id"),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [index("refunds_order_idx").on(t.orderId)],
);

// ---------------------------------------------------------------------------
// Shipments
// ---------------------------------------------------------------------------

/** Ordered: a tracking update may only move a shipment forward (RTO and CANCELLED are terminal branches). */
export const shipmentStatus = pgEnum("shipment_status", [
  "BOOKED", // label created, waiting for pickup
  "PICKED_UP",
  "IN_TRANSIT",
  "OUT_FOR_DELIVERY",
  "DELIVERED",
  "RTO", // returned to origin: couldn't be delivered
  "CANCELLED",
]);

export const shipments = pgTable(
  "shipments",
  {
    id: id(),
    orderId: uuid("order_id").notNull().unique().references(() => orders.id),
    provider: text("provider").notNull(),
    providerShipmentId: text("provider_shipment_id").notNull(),
    awb: text("awb").notNull(),
    courierName: text("courier_name").notNull(),
    trackingUrl: text("tracking_url"),
    labelUrl: text("label_url"),
    status: shipmentStatus("status").notNull().default("BOOKED"),
    pickupScheduledFor: timestamp("pickup_scheduled_for", { withTimezone: true }),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [uniqueIndex("shipments_provider_awb_uq").on(t.provider, t.awb)],
);

/** Every tracking update we accept, deduplicated by the provider's event id. */
export const shipmentEvents = pgTable(
  "shipment_events",
  {
    id: id(),
    shipmentId: uuid("shipment_id").notNull().references(() => shipments.id),
    providerEventId: text("provider_event_id").notNull(),
    status: shipmentStatus("status").notNull(),
    description: text("description"),
    location: text("location"),
    occurredAt: timestamp("occurred_at", { withTimezone: true }).notNull(),
    receivedAt: timestamp("received_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [
    uniqueIndex("shipment_events_provider_event_uq").on(t.shipmentId, t.providerEventId),
    index("shipment_events_shipment_idx").on(t.shipmentId, t.occurredAt),
  ],
);

// ---------------------------------------------------------------------------
// Buyer protection claims (decision D6: no size returns; protection when an item isn't as
// described, arrives damaged, is the wrong item, or never arrives)
// ---------------------------------------------------------------------------

export const claimReason = pgEnum("claim_reason", ["NOT_AS_DESCRIBED", "DAMAGED", "WRONG_ITEM", "NOT_RECEIVED"]);
export const claimStatus = pgEnum("claim_status", [
  "OPEN", // waiting for the seller
  "ESCALATED", // seller disputed it; YOLT decides
  "REFUNDED", // resolved with a full refund
  "REJECTED", // resolved without a refund (YOLT decision)
  "WITHDRAWN", // buyer withdrew it
]);

export const claims = pgTable(
  "claims",
  {
    id: id(),
    orderId: uuid("order_id").notNull().references(() => orders.id),
    buyerId: uuid("buyer_id").notNull().references(() => users.id),
    sellerId: uuid("seller_id").notNull().references(() => sellers.id),
    reason: claimReason("reason").notNull(),
    description: text("description").notNull(),
    photoUrls: jsonb("photo_urls").$type<string[]>().notNull().default([]),
    status: claimStatus("status").notNull().default("OPEN"),
    sellerResponse: text("seller_response"),
    sellerRespondedAt: timestamp("seller_responded_at", { withTimezone: true }),
    resolvedAt: timestamp("resolved_at", { withTimezone: true }),
    refundId: uuid("refund_id").references(() => refunds.id),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    // One claim per order at a time; a resolved claim can't be reopened by a second one.
    uniqueIndex("claims_one_per_order").on(t.orderId),
    index("claims_seller_status_idx").on(t.sellerId, t.status),
  ],
);

// ---------------------------------------------------------------------------
// Trust and retention
// ---------------------------------------------------------------------------

export const reviews = pgTable(
  "reviews",
  {
    id: id(),
    orderItemId: uuid("order_item_id").notNull().unique().references(() => orderItems.id),
    sellerId: uuid("seller_id").notNull().references(() => sellers.id),
    buyerId: uuid("buyer_id").notNull().references(() => users.id),
    rating: smallint("rating").notNull(),
    accuracyRating: smallint("accuracy_rating"),
    body: text("body"),
    photoUrls: jsonb("photo_urls").$type<string[]>().notNull().default([]),
    sellerReply: text("seller_reply"),
    sellerRepliedAt: timestamp("seller_replied_at", { withTimezone: true }),
    createdAt: createdAt(),
  },
  (t) => [
    index("reviews_seller_idx").on(t.sellerId, t.createdAt),
    check("reviews_rating_range", sql`${t.rating} BETWEEN 1 AND 5`),
  ],
);

export const savedItems = pgTable(
  "saved_items",
  {
    userId: uuid("user_id").notNull().references(() => users.id),
    listingId: uuid("listing_id").notNull().references(() => listings.id),
    createdAt: createdAt(),
  },
  (t) => [primaryKey({ columns: [t.userId, t.listingId] })],
);

export const follows = pgTable(
  "follows",
  {
    userId: uuid("user_id").notNull().references(() => users.id),
    sellerId: uuid("seller_id").notNull().references(() => sellers.id),
    createdAt: createdAt(),
  },
  (t) => [primaryKey({ columns: [t.userId, t.sellerId] }), index("follows_seller_idx").on(t.sellerId)],
);

/** The bag holds nothing: adding an item never reserves it. Reservation starts at checkout. */
export const bagItems = pgTable(
  "bag_items",
  {
    userId: uuid("user_id").notNull().references(() => users.id),
    listingId: uuid("listing_id").notNull().references(() => listings.id),
    createdAt: createdAt(),
  },
  (t) => [primaryKey({ columns: [t.userId, t.listingId] })],
);

// ---------------------------------------------------------------------------
// Operations
// ---------------------------------------------------------------------------

/** Domain events written in the same transaction as the change; a job delivers them (notifications, search indexing). */
export const outboxEvents = pgTable(
  "outbox_events",
  {
    id: id(),
    type: text("type").notNull(),
    payload: jsonb("payload").notNull(),
    createdAt: createdAt(),
    processedAt: timestamp("processed_at", { withTimezone: true }),
  },
  (t) => [index("outbox_unprocessed_idx").on(t.createdAt).where(sql`${t.processedAt} IS NULL`)],
);

export const auditEvents = pgTable(
  "audit_events",
  {
    id: id(),
    actorId: uuid("actor_id"),
    actorRole: text("actor_role").notNull(),
    action: text("action").notNull(),
    entity: text("entity").notNull(),
    entityId: uuid("entity_id").notNull(),
    before: jsonb("before"),
    after: jsonb("after"),
    reason: text("reason"),
    createdAt: createdAt(),
  },
  (t) => [index("audit_entity_idx").on(t.entity, t.entityId)],
);

// ---------------------------------------------------------------------------
// Landing page curation, buyer preferences, seller applications
// ---------------------------------------------------------------------------

export const homepageSlotKind = pgEnum("homepage_slot_kind", ["FEATURED_STORE", "GRAILS", "EDIT"]);

/**
 * Staff-curated homepage content. A slot is current when now is inside its (optional) window;
 * the latest current slot per kind wins. Listing ids are kept in curated order and checked
 * when the slot is saved; the landing read re-checks that each piece is still live.
 */
export const homepageSlots = pgTable(
  "homepage_slots",
  {
    id: id(),
    kind: homepageSlotKind("kind").notNull(),
    /** FEATURED_STORE only. */
    sellerId: uuid("seller_id").references(() => sellers.id),
    /** EDIT only (3-40 characters). */
    title: text("title"),
    /** GRAILS and EDIT: up to 12 listing ids, in display order. */
    listingIds: jsonb("listing_ids").$type<string[]>().notNull().default([]),
    startsAt: timestamp("starts_at", { withTimezone: true }),
    endsAt: timestamp("ends_at", { withTimezone: true }),
    createdBy: uuid("created_by").notNull().references(() => users.id),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    index("homepage_slots_kind_idx").on(t.kind, t.createdAt),
    check("homepage_slots_window_order", sql`${t.startsAt} IS NULL OR ${t.endsAt} IS NULL OR ${t.endsAt} > ${t.startsAt}`),
    check(
      "homepage_slots_shape",
      sql`(${t.kind} = 'FEATURED_STORE' AND ${t.sellerId} IS NOT NULL) OR (${t.kind} <> 'FEATURED_STORE' AND ${t.sellerId} IS NULL)`,
    ),
  ],
);

/** Optional, skippable buyer preferences (docs/user-flows.md B-F4). Sizes are stored normalised. */
export const buyerPreferences = pgTable("buyer_preferences", {
  userId: uuid("user_id").primaryKey().references(() => users.id),
  sizes: text("sizes").array().notNull().default(sql`'{}'::text[]`),
  styles: text("styles").array().notNull().default(sql`'{}'::text[]`),
  /** Per-piece budget ceiling; null means no limit. */
  maxBudgetPaise: integer("max_budget_paise"),
  updatedAt: updatedAt(),
});

export const applicationVolume = pgEnum("application_volume", ["UNDER_20", "BETWEEN_20_50", "BETWEEN_50_100", "OVER_100"]);
export const applicationStatus = pgEnum("application_status", ["NEW", "CONTACTED", "ONBOARDED", "REJECTED"]);

/** "Apply to sell" form submissions (guests allowed). Staff follow up and onboard by hand in the pilot. */
export const sellerApplications = pgTable(
  "seller_applications",
  {
    id: id(),
    storeName: text("store_name").notNull(),
    /** No @, lowercase, Instagram's allowed characters. */
    instagramHandle: text("instagram_handle").notNull(),
    city: text("city").notNull(),
    whatTheySell: text("what_they_sell").notNull(),
    piecesPerMonth: applicationVolume("pieces_per_month").notNull(),
    /** E.164 */
    phone: text("phone").notNull(),
    userId: uuid("user_id").references(() => users.id),
    status: applicationStatus("status").notNull().default("NEW"),
    adminNote: text("admin_note"),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    index("seller_applications_status_idx").on(t.status, t.createdAt),
    // One open application per phone and per handle; a repeat submission returns the existing one.
    uniqueIndex("seller_applications_open_phone").on(t.phone).where(sql`${t.status} IN ('NEW', 'CONTACTED')`),
    uniqueIndex("seller_applications_open_handle").on(t.instagramHandle).where(sql`${t.status} IN ('NEW', 'CONTACTED')`),
  ],
);

/** One row per rate-limited attempt. The key is an HMAC, so no raw IPs or phone numbers are stored. */
export const rateLimitHits = pgTable(
  "rate_limit_hits",
  {
    id: id(),
    key: text("key").notNull(),
    createdAt: createdAt(),
  },
  (t) => [index("rate_limit_hits_key_idx").on(t.key, t.createdAt)],
);

// ---------------------------------------------------------------------------
// Listing completeness
// ---------------------------------------------------------------------------

export type Listing = typeof listings.$inferSelect;
/** A listing past DRAFT: `listings_complete_unless_draft` guarantees these fields. */
export type CompleteListing = Listing & {
  title: string;
  category: string;
  condition: NonNullable<Listing["condition"]>;
  pricePaise: number;
};

export function isComplete(l: Listing): l is CompleteListing {
  return l.title !== null && l.category !== null && l.condition !== null && l.pricePaise !== null;
}

/** For listings the database already guarantees are complete (anything not DRAFT). */
export function asComplete(l: Listing): CompleteListing {
  if (!isComplete(l)) throw new Error(`listing ${l.id} is incomplete (status ${l.status})`);
  return l;
}
